  ],
  "confidence": "low",
  "narrative": "Starting from a historical anchor near 0.44, the analysis weighs mixed and correlated signals. The net effect, after considering opposition consolidation, market signals, and fragmentation risks, yields a low posterior around 9% with a broad uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate of obtaining a two-thirds majority (133+ seats) under Hungary's current electoral framework across elections since 1990; 4 of 9 completed cycles reached 2/3."
    },
    "factor_updates": [
      {
        "factor": "Opposition unification around the TISZA platform",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation behind TISZA raises the probability of the anti-Orbán bloc reaching 133+ seats, partially offsetting Fidesz advantages and contributing to a non-negligible chance of a 2/3 majority for any side."
      },
      {
        "factor": "Market signals pricing in a regime change",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Financial-market commentary suggests odds of a non-Fidesz majority are priced in, signaling a shift away from a guaranteed 2/3, thereby nudging the posterior upward from a purely static base."
      },
      {
        "factor": "Mobilization risk of dormant Fidesz supporters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Analyses indicate a mobilization margin among Fidesz supporters could help preserve a 2/3 if favorable conditions persist, counterbalancing other uncertainties and contributing to a non-zero probability."
      },
      {
        "factor": "Divergent poll results and uncertainty",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "Conflicting polls reduce confidence in any single trajectory and introduce ambiguity about seat translation, dampening a clear path to 2/3 and supporting a lower posterior."
      },
      {
        "factor": "Electoral-system bias toward the largest camp",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "The system tends to translate large vote shares into outsized seat shares for the leading camp; if a leading camp remains viable, this tilts probability upward toward a 2/3 outcome."
      },
      {
        "factor": "Cross-party entrants and threshold dynamics (fragmentation risk)",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Entrants like Our Homeland and other smaller parties can fragment the anti-government vote, reducing the likelihood that any single coalition reaches 133+ seats and pulling the probability downward."
      }
    ],
    "synthesis_rationale": "The posterior fuses a modest upward push from consolidation and market signals with downward pressures from polling divergence and fragmentation risk. Because polling and seat-projection signals are correlated, updates are not treated as independent; the net result is a low-probability event (~9%) with a wide confidence interval. Given the volatility and turnout sensitivity inherent to Hungary's 2026 race, the calibration acknowledges substantial caveats and the potential for regime-change expectations to shift quickly."
  }
}

